use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut toks: Vec<int> = []
    for w in text.split_whitespace() {
        toks.push(w.parse::<int>().unwrap_or(0))
    }
    let limit: int = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut cnt: Vec<int> = [0; 200001]
    let mut last: Vec<int> = [0; 200001]
    sieve[0] = false
    sieve[1] = false
    let mut i: int = 2
    while i * i <= limit {
        if sieve[i] {
            let mut j: int = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c: int = 0
    let mut l: int = 0
    let mut k: int = 0
    while k <= limit {
        if sieve[k] {
            c += 1
            l = k
        }
        cnt[k] = c
        last[k] = l
        k += 1
    }
    if toks.len() == 0 {
        return
    }
    let t = toks[0]
    let mut q: int = 1
    while q <= t && q < toks.len() {
        let n = toks[q]
        if last[n] == 0 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
        q += 1
    }
}

